window.products.push({"id":392992,"name":"Umbra Dorset Curtain Rod for Window, Includes Knob Finials, Brackets and Mounting Hardware, 36-72\"(91-183cm), Matte Black","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71Dp2XQk0eL._AC_SL1500_.jpg","description":"If you’re seeking a timeless yet modern addition to your window dressings this charming drapery rod will end your search. Dorset is a classic curtain rod with modern refinement. Simplistic in form and well balanced, it can work in homes of different sizes and decor styles. This metal rod sports a nickel finish and knob-shaped finials influenced by classic millwork. Dorset is a telescoping rod and holds medium to light-weight curtains up to 22 lbs. Available in two sizes: 36 to 72 inches (71.1-121.9 cm) 72-144 inches (121.9-223.5 cm). The diameter of the rod is 1-inch (2.5 cm).","images":["https://m.media-amazon.com/images/I/71Dp2XQk0eL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Umbra","source_asin":"B08CFYR97R","category_path":"Home & Kitchen"},"sku":"BM-392992","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B08CFYR97R","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B08CFYR97R","price_pending":true,"merchant_ready":false});
